package br.com.onda;
import android.app.*;
import android.content.*;
import android.os.*;
import android.view.*;
import android.widget.*;
import androidx.media3.common.*;
import androidx.media3.session.*;
import com.google.common.util.concurrent.ListenableFuture;
import java.util.*;
@androidx.media3.common.util.UnstableApi
public class QueueActivity extends Activity {
 MediaController player;ListView list;Button clear;AlertDialog activeDialog;
 private ListenableFuture<MediaController> connection;private BaseAdapter adapter;private TextView status;private final List<MediaItem> items=new ArrayList<>();private final Handler handler=new Handler(Looper.getMainLooper());private boolean started;
 private final Player.Listener listener=new Player.Listener(){@Override public void onEvents(Player p,Player.Events events){if(events.contains(Player.EVENT_TIMELINE_CHANGED)||events.contains(Player.EVENT_MEDIA_ITEM_TRANSITION)||events.contains(Player.EVENT_SHUFFLE_MODE_ENABLED_CHANGED)||events.contains(Player.EVENT_REPEAT_MODE_CHANGED))render();}};
 @Override public void onCreate(Bundle state){super.onCreate(state);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);Ui.background(root);root.setOnApplyWindowInsetsListener((v,i)->{root.setPadding(Ui.dp(this,20),Ui.dp(this,12)+i.getSystemWindowInsetTop(),Ui.dp(this,20),Ui.dp(this,12)+i.getSystemWindowInsetBottom());return i;});setContentView(root);
  LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);Button back=Ui.button(this,"‹",v->finish());back.setContentDescription("Voltar da fila");top.addView(back,new LinearLayout.LayoutParams(Ui.dp(this,48),Ui.dp(this,48)));TextView title=Ui.text(this,"Fila de reprodução",23,Ui.TEXT);Ui.bold(title);top.addView(title,new LinearLayout.LayoutParams(0,-2,1));root.addView(top);
  TextView intro=Ui.text(this,"Toque em uma faixa para escolher a próxima ou alterar a ordem. Reorganizar usa a ordem manual e mantém a música atual.",14,Ui.MUTED);intro.setPadding(0,Ui.dp(this,14),0,Ui.dp(this,12));root.addView(intro);status=Ui.text(this,"Conectando ao tocador…",13,Ui.CYAN);root.addView(status);
  list=new ListView(this);list.setContentDescription("Músicas na fila de reprodução");list.setDivider(null);list.setDividerHeight(Ui.dp(this,7));adapter=new BaseAdapter(){public int getCount(){return items.size();}public Object getItem(int i){return items.get(i);}public long getItemId(int i){return i;}public View getView(int i,View old,ViewGroup parent){LinearLayout row;TextView a,b;if(old==null){row=new LinearLayout(QueueActivity.this);row.setOrientation(LinearLayout.VERTICAL);row.setPadding(Ui.dp(QueueActivity.this,14),Ui.dp(QueueActivity.this,12),Ui.dp(QueueActivity.this,14),Ui.dp(QueueActivity.this,12));a=Ui.text(QueueActivity.this,"",15,Ui.TEXT);Ui.bold(a);a.setMaxLines(1);a.setEllipsize(android.text.TextUtils.TruncateAt.END);b=Ui.text(QueueActivity.this,"",12,Ui.MUTED);b.setMaxLines(2);row.addView(a);row.addView(b);row.setTag(new TextView[]{a,b});}else{row=(LinearLayout)old;TextView[] t=(TextView[])row.getTag();a=t[0];b=t[1];}MediaItem item=items.get(i);int current=player==null?-1:player.getCurrentMediaItemIndex();a.setText((i+1)+". "+(item.mediaMetadata.title==null?"Sem título":item.mediaMetadata.title));b.setText((i==current?"Atual":i<current?"Anterior":"A seguir")+" • "+(item.mediaMetadata.artist==null?"":item.mediaMetadata.artist));Ui.card(row,i==current);row.setContentDescription("Opções da faixa "+(i+1)+": "+item.mediaMetadata.title);return row;}};list.setAdapter(adapter);list.setOnItemClickListener((p,v,index,id)->edit(index));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,0,1);lp.topMargin=Ui.dp(this,12);lp.bottomMargin=Ui.dp(this,12);root.addView(list,lp);
  clear=Ui.button(this,"Remover próximas",v->clearNext());clear.setContentDescription("Remover próximas músicas da fila");root.addView(clear,new LinearLayout.LayoutParams(-1,Ui.dp(this,48)));clear.setEnabled(false);
  connection=new MediaController.Builder(this,new SessionToken(this,new ComponentName(this,PlaybackService.class))).buildAsync();connection.addListener(()->{if(isDestroyed())return;try{player=connection.get();if(started)player.addListener(listener);render();list.setSelection(Math.max(0,player.getCurrentMediaItemIndex()));}catch(Exception e){status.setText("Não foi possível conectar ao tocador.");}},handler::post);
 }
 void edit(int index){if(player==null||index<0||index>=items.size())return;List<MediaItem> before=QueueEdit.snapshot(player);int current=player.getCurrentMediaItemIndex();if(index>=before.size())return;boolean future=index>current;String[] labels=future?new String[]{"Ouvir agora","Colocar como próxima","Mover para cima","Mover para baixo","Remover da fila"}:new String[]{"Ouvir agora"};String[] actions={"play","next","up","down","remove"};activeDialog=new AlertDialog.Builder(this).setTitle(String.valueOf(before.get(index).mediaMetadata.title)).setItems(labels,(d,i)->{QueueEdit.change(this,player,before,current,index,actions[i]);}).setNegativeButton("Cancelar",null).show();}
 private void clearNext(){if(player==null)return;List<MediaItem> before=QueueEdit.snapshot(player);int current=player.getCurrentMediaItemIndex();activeDialog=new AlertDialog.Builder(this).setTitle("Remover próximas músicas?").setMessage("A música atual continua e a fila termina depois dela. A repetição será desativada. Seus arquivos e playlists ficam guardados.").setPositiveButton("Remover próximas",(d,w)->{QueueEdit.change(this,player,before,current,-1,"clear");}).setNegativeButton("Cancelar",null).show();}
 private void render(){if(!started||player==null)return;if(activeDialog!=null&&activeDialog.isShowing())activeDialog.dismiss();items.clear();items.addAll(QueueEdit.snapshot(player));adapter.notifyDataSetChanged();int current=player.getCurrentMediaItemIndex();int next=Math.max(0,items.size()-current-1);status.setText(items.isEmpty()?"Sua fila está vazia. Segure uma música na biblioteca para adicioná-la.":items.size()+" faixas • "+next+" próximas"+(player.getShuffleModeEnabled()?" • aleatório ativado":""));clear.setEnabled(next>0);}
 @Override protected void onStart(){super.onStart();started=true;if(player!=null){player.addListener(listener);render();}}
 @Override protected void onStop(){started=false;if(player!=null)player.removeListener(listener);if(activeDialog!=null)activeDialog.dismiss();super.onStop();}
 @Override public void onDestroy(){handler.removeCallbacksAndMessages(null);if(connection!=null)MediaController.releaseFuture(connection);super.onDestroy();}
}
